"""Probe IDM on videos generated by the real DriveLaW world model.

This intentionally evaluates only a small number of scenarios and saves raw
artifacts.  It does not compute aggregate metrics.
"""

from __future__ import annotations

import json
import os
import sys
import types
from pathlib import Path
from typing import Any, Dict

import hydra
import torch

# Recent diffusers releases probe optional backends at import time, while the
# XVO environment uses a CUDA-only PyTorch build. Provide the complete small
# API surface diffusers expects for unavailable XPU/MPS backends.
class _UnavailableTorchBackend:
    @staticmethod
    def is_available() -> bool:
        return False

    @staticmethod
    def empty_cache() -> None:
        return None

    @staticmethod
    def device_count() -> int:
        return 0

    @staticmethod
    def manual_seed(*args: Any, **kwargs: Any) -> None:
        return None

    @staticmethod
    def manual_seed_all(*args: Any, **kwargs: Any) -> None:
        return None

    @staticmethod
    def current_device() -> int:
        return 0

    @staticmethod
    def set_device(*args: Any, **kwargs: Any) -> None:
        return None


if not hasattr(torch, "xpu"):
    torch.xpu = _UnavailableTorchBackend()
if not hasattr(torch, "mps"):
    torch.mps = _UnavailableTorchBackend()

# TorchAO is not used by this probe, but recent diffusers imports its
# quantizer registry eagerly. PyTorch 2.0 has no float8 dtype symbols.
if not hasattr(torch, "float8_e4m3fn"):
    torch.float8_e4m3fn = torch.float16
if not hasattr(torch, "float8_e5m2"):
    torch.float8_e5m2 = torch.float16

# Newer diffusers annotates optional parallelism classes with DeviceMesh.
# This probe does not use that path, and PyTorch 2.0 does not expose it.
if hasattr(torch, "distributed") and not hasattr(torch.distributed, "device_mesh"):
    class _DeviceMeshCompat:
        DeviceMesh = object

    torch.distributed.device_mesh = _DeviceMeshCompat()

# Diffusers imports context-parallel helpers eagerly. They are not used by
# this single-GPU probe, and the module is absent from PyTorch 2.0.
if hasattr(torch, "distributed") and "torch.distributed._functional_collectives" not in sys.modules:
    _functional_collectives = types.ModuleType("torch.distributed._functional_collectives")
    _functional_collectives.AsyncCollectiveTensor = object
    for _name in (
        "all_gather_tensor",
        "all_reduce",
        "reduce_scatter_tensor",
        "wait_tensor",
    ):
        setattr(_functional_collectives, _name, lambda *args, **kwargs: None)
    sys.modules["torch.distributed._functional_collectives"] = _functional_collectives

from diffusers.utils import export_to_video
from hydra.utils import instantiate
from omegaconf import DictConfig, OmegaConf

from navsim.common.dataloader import SceneLoader
from navsim.agents.videodrive.idm_xvo_style import build_resim_idm_for_drivelaw


CONFIG_PATH = "config/pdm_scoring"
CONFIG_NAME = "default_run_pdm_score"


def _load_idm(cfg: DictConfig, device: torch.device) -> torch.nn.Module:
    probe = cfg.probe
    checkpoint_path = Path(str(probe.idm_checkpoint))
    if not checkpoint_path.is_file():
        raise FileNotFoundError(f"IDM checkpoint not found: {checkpoint_path}")

    model = build_resim_idm_for_drivelaw(
        num_waypoints=8,
        xvo_root=str(probe.xvo_root),
        flownet_root=str(probe.flownet_root),
        xvo_checkpoint_path=str(probe.xvo_checkpoint),
        freeze_backbone=True,
    ).to(device)
    checkpoint = torch.load(checkpoint_path, map_location=device)
    state_dict = checkpoint.get("model_state_dict", checkpoint)
    state_dict = {
        key.removeprefix("module."): value
        for key, value in state_dict.items()
    }
    model.load_state_dict(state_dict)
    model.eval()
    return model


def _build_features(agent: Any, agent_input: Any) -> Dict[str, torch.Tensor]:
    features: Dict[str, torch.Tensor] = {}
    for builder in agent.get_feature_builders():
        features.update(builder.compute_features(agent_input))
    return {key: value.unsqueeze(0) for key, value in features.items()}


def _save_video(video: torch.Tensor, path: Path, fps: float) -> None:
    # VideoDrive returns (1, T, C, H, W) in [0, 1] or [-1, 1].
    video = video.detach().float().cpu()
    if video.ndim == 5:
        video = video[0]
    if video.ndim != 4 or video.shape[1] not in (1, 3):
        raise ValueError(f"Expected video shaped (T,C,H,W), got {tuple(video.shape)}")
    if video.min() < 0:
        video = (video + 1.0) * 0.5
    frames = [frame.permute(1, 2, 0).clamp(0, 1).numpy() for frame in video]
    export_to_video(frames, str(path), fps=fps)


@hydra.main(config_path=CONFIG_PATH, config_name=CONFIG_NAME, version_base=None)
def main(cfg: DictConfig) -> None:
    probe = cfg.probe
    output_dir = Path(str(probe.output_dir))
    video_dir = output_dir / "videos"
    frame_dir = output_dir / "frames"
    trajectory_dir = output_dir / "trajectories"
    for directory in (video_dir, frame_dir, trajectory_dir):
        directory.mkdir(parents=True, exist_ok=True)

    local_rank = int(os.environ.get("LOCAL_RANK", 0))
    device = torch.device(f"cuda:{local_rank}" if torch.cuda.is_available() else "cpu")
    if device.type == "cuda":
        torch.cuda.set_device(local_rank)

    agent = instantiate(cfg.agent)
    agent.device = device
    agent.initialize()
    agent.eval()
    idm = _load_idm(cfg, device)

    scene_filter = instantiate(cfg.train_test_split.scene_filter)
    scene_loader = SceneLoader(
        sensor_blobs_path=Path(cfg.sensor_blobs_path),
        data_path=Path(cfg.navsim_log_path),
        scene_filter=scene_filter,
        sensor_config=agent.get_sensor_config(),
        load_image_path=False,
    )

    tokens = sorted(scene_loader.tokens)
    limit = int(probe.limit)
    if limit > 0:
        tokens = tokens[:limit]

    manifest = {
        "num_samples": len(tokens),
        "idm_checkpoint": str(probe.idm_checkpoint),
        "world_model_config": str(cfg.agent.config_file),
        "tokens": [],
    }

    with torch.inference_mode():
        for index, token in enumerate(tokens):
            print(f"[{index + 1}/{len(tokens)}] {token}", flush=True)
            agent_input = scene_loader.get_agent_input_from_token(token)
            scene = scene_loader.get_scene_from_token(token)
            features = _build_features(agent, agent_input)
            predictions = agent.forward(features)

            world_traj = predictions["actions_tensor"].detach().float().cpu()
            generated_video = predictions["generated_future_video"].detach().float().cpu()
            idm_clip = predictions["idm_clip"].to(device)
            idm_meta = predictions["idm_meta"]
            idm_traj = idm(idm_clip, meta=idm_meta).detach().float().cpu()[0]

            gt_target = agent.get_target_builders()[0].compute_targets(scene)
            gt_traj = gt_target["trajectory"]
            if not torch.is_tensor(gt_traj):
                gt_traj = torch.as_tensor(gt_traj)
            gt_traj = gt_traj.float().cpu()

            stem = f"{index:04d}_{token}"
            torch.save(generated_video, frame_dir / f"{stem}_generated_frames.pt")
            torch.save(
                {
                    "world_model_trajectory": world_traj,
                    "idm_trajectory_from_generated_video": idm_traj,
                    "gt_trajectory": gt_traj,
                    "idm_meta": vars(idm_meta),
                },
                trajectory_dir / f"{stem}_trajectories.pt",
            )
            _save_video(generated_video, video_dir / f"{stem}_generated.mp4", fps=float(idm_meta.fps))
            manifest["tokens"].append(token)

    (output_dir / "manifest.json").write_text(
        json.dumps(manifest, indent=2, ensure_ascii=True),
        encoding="utf-8",
    )
    print(f"Saved probe artifacts to {output_dir}")


if __name__ == "__main__":
    main()
